const MINT_URL = "https://staging.crossmint.com/api/2022-06-09/collections/default/nfts";
const ACTION_URL_BASE = "https://staging.crossmint.com/api/2022-06-09/actions/";
const OUTPUT_PATH = "/home/user/poll_result.json";
const CHAIN = "polygon-amoy";
const MAX_ATTEMPTS = 5;
const POLL_INTERVAL_MS = 2000;

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

const writeResult = (result) => {
  fs.writeFileSync(OUTPUT_PATH, JSON.stringify(result, null, 2));
};

const run = async () => {
  const apiKey = process.env.CROSSMINT_API_KEY;
  const result = {
    actionId: apiKey ? "" : "mock-action-id",
    final_status: "unknown",
    poll_attempts: 0,
    mint_chain: CHAIN,
  };

  if (!apiKey) {
    result.error = "CROSSMINT_API_KEY is not set";
    writeResult(result);
    return;
  }

  try {
    const mintResponse = await fetch(MINT_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-api-key": apiKey,
      },
      body: JSON.stringify({
        recipient: `email:demo@example.com:${CHAIN}`,
        metadata: {
          name: "Poll Test NFT",
          description: "Testing async polling",
          image: "https://example.com/poll.png",
        },
      }),
    });

    if (!mintResponse.ok) {
      const errorBody = await mintResponse.text();
      result.error = `Mint request failed: ${mintResponse.status} ${mintResponse.statusText} - ${errorBody}`;
      writeResult(result);
      return;
    }

    const mintData = await mintResponse.json();
    const actionId = mintData.actionId;

    if (!actionId) {
      result.error = "Mint response missing actionId";
      writeResult(result);
      return;
    }

    result.actionId = actionId;

    for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt += 1) {
      result.poll_attempts = attempt;
      const pollResponse = await fetch(`${ACTION_URL_BASE}${actionId}`, {
        headers: {
          "x-api-key": apiKey,
        },
      });

      if (!pollResponse.ok) {
        const errorBody = await pollResponse.text();
        result.error = `Poll request failed: ${pollResponse.status} ${pollResponse.statusText} - ${errorBody}`;
        writeResult(result);
        return;
      }

      const pollData = await pollResponse.json();
      const status = pollData?.status;
      if (typeof status === "string") {
        result.final_status = status;
      }

      if (status && status !== "pending") {
        writeResult(result);
        return;
      }

